    mut s: *mut ZopfliBlockState,
    mut pos: size_t,
    mut limit: *mut size_t,
    mut sublen: *mut c_ushort,
    mut distance: *mut c_ushort,
    mut length: *mut c_ushort,
) -> c_int {
    // SAFETY: Caller provides a valid pointer to ZopfliBlockState as required by the original function contract.
    let s_ref = unsafe { &*s };
    let lmc = s_ref.lmc;
    if lmc.is_null() {
        return 0 as c_int;
    }

    let lmcpos: size_t = pos.wrapping_sub(s_ref.blockstart);
    let idx = lmcpos as isize;

    // SAFETY: lmc is non-null and lmcpos indexes the same cache entry as in the original implementation.
    let cached_len: c_ushort = unsafe { *(*lmc).length.offset(idx) };
    // SAFETY: lmc is non-null and lmcpos indexes the same cache entry as in the original implementation.
    let cached_dist: c_ushort = unsafe { *(*lmc).dist.offset(idx) };

    let cache_available = cached_len as c_int == 0 || cached_dist as c_int != 0;
    if !cache_available {
        return 0 as c_int;
    }

    let limit_val = *limit;
    let cached_len_size = cached_len as size_t;

    let limit_ok_for_cache = if limit_val == ZOPFLI_MAX_MATCH as size_t || cached_len_size <= limit_val {
        true
    } else if !sublen.is_null() {
        ZopfliMaxCachedSublen(lmc, lmcpos, cached_len_size) as size_t >= limit_val
    } else {
        false
    };

    if !limit_ok_for_cache {
        return 0 as c_int;
    }

    if sublen.is_null()
        || cached_len as c_uint <= ZopfliMaxCachedSublen(lmc, lmcpos, cached_len_size)
    {
        let out_len: c_ushort = if cached_len_size > limit_val {
            limit_val as c_ushort
        } else {
            cached_len
        };
        *length = out_len;

        if !sublen.is_null() {
