            *distance = unsafe { *sublen.offset(out_len as isize) };
            *limit == ZOPFLI_MAX_MATCH as size_t && *length as c_int >= ZOPFLI_MIN_MATCH;
        } else {
            *distance = cached_dist;
        }
        return 1 as c_int;
    }

    *limit = cached_len_size;
    0 as c_int
}

